from datetime import datetime

from flask import Flask, render_template

app = Flask(__name__)

TASKS = [
    {"id": 1, "title": "Купить молоко", "done": False, "created": "2026-02-11"},
    {"id": 2, "title": "Написать отчёт", "done": True, "created": "2026-02-09"},
]


@app.get("/tasks")
def task_page():
    return render_template(
        "tasks.html",
        tasks=TASKS,
        page_title="Мои задачи",
        today=datetime.now().strftime("%d.%m.%Y"),
    )


app.run(debug=True)

{% extends "base.html" %}

{% block title %}{{ page_title }} — Мои задачи{% endblock %}

{% block content %}
  <h1>{{ page_title | trim | upper }}</h1>

  {% if tasks %}
    <p>Всего записей: {{ tasks | length }}</p>
    <ul class="task-list">
      {% for task in tasks %}
        <li class="task-item {{ 'done' if task.done else 'open' }}">
          <span class="num">{{ loop.index }}.</span>
          <span class="title">{{ task.title }}</span>
          {% if not task.done %}
            <span class="badge">в работе</span>
          {% endif %}
        </li>
      {% endfor %}
    </ul>
  {% else %}
    <p>Задач пока нет. <a href="{{ url_for('new_task') }}">Добавьте первую</a>.</p>
  {% endif %}
{% endblock %}
